syntax:
The `common_type` is usually implemented (though implementation details might vary across compilers) using recursive template instantiation:

```c++
template <class T> struct common_type<T> { typedef T type; }; // Base case

template <class T, class U> struct common_type {
  typedef decltype(true ? std::declval<T>() : std::declval<U>()) type;
};

template <class T, class U, class... V>
struct common_type<T, U, V...> {
  typedef typename common_type<typename common_type<T, U>::type, V...>::type type;
};
```

Note that `std::declval` is used to avoid creating actual objects; it's a compile-time mechanism for determining the type of an expression without object construction.

`common_type_t` is simply an alias which makes using the `common_type` struct more convenient:

code_example:
#include <iostream>
#include <type_traits>
#include <string>
#include <vector>
int main() {
  std::cout << typeid(std::common_type_t<int, double, long long>).name() << std::endl; //Prints 'long long'
  std::cout << typeid(std::common_type_t<std::string, const char*>).name() << std::endl; //Prints 'std::string'
  std::cout << typeid(std::common_type_t<std::vector<int>, std::vector<double>>).name() << std::endl; //Implementation dependent (often same as the first vector)
  return 0;
}
